query Regime {
  regime {
    session
    label
    headline
    unknownReason {
      code
      kind
      guideTerm
      kindText
      cause {
        links {
          level
          subject
          status
          message
          runId
        }
      }
    }
    scores {
      macroRisk {
        value
        unknown {
          code
          kind
          guideTerm
          kindText
          cause {
            links {
              level
              subject
              status
              message
              runId
            }
          }
        }
        feature
        coverageFeature
        threshold
      }
      marketStress {
        value
        unknown {
          code
          kind
          guideTerm
          kindText
          cause {
            links {
              level
              subject
              status
              message
              runId
            }
          }
        }
        feature
        coverageFeature
        threshold
      }
      fragility {
        value
        unknown {
          code
          kind
          guideTerm
          kindText
          cause {
            links {
              level
              subject
              status
              message
              runId
            }
          }
        }
        feature
        coverageFeature
        threshold
      }
    }
    sizing {
      label
      multiplier
      enabled
      unknownMultiplier
      multipliers {
        label
        multiplier
      }
      screeners {
        screenerId
        name
        enabled
        pauseIn
      }
    }
    indicators {
      key
      pace
      plainName
      technicalName
      oneLiner
      whyItMatters
      whatOnMeans
      before {
        episode
        line
      }
      leadTime
      falseAlarms
      links {
        title
        url
      }
      value
      unknown {
        code
        kind
        guideTerm
        kindText
        cause {
          links {
            level
            subject
            status
            message
            runId
          }
        }
      }
      format
      status
      changed
      feature
      verdictFeature
