        min
        max
      }
      threshold
      direction
      how {
        text
        url
      }
    }
  }
}

query StatusStrip($admin: Boolean!) {
  session {
    date
    newer {
      date
      state
    }
  }
  screeners {
    id
    name
    notRun {
      code
      kindText
    }
  }
  nightlyRuns(limit: 1) @include(if: $admin) {
    runId
    session
    status
    problems
    steps {
      name
      status
    }
  }
  completeness(sessions: 1) @include(if: $admin) {
    sessions
    lastClosed
  }
}

query SessionDate {
  session {
    date
  }
}

query IdeasPage($first: Int!, $after: String, $names: [FeatureName!]!) {
  ideas(first: $first, after: $after) {
    session
    total
    hasMore
    nextCursor
    pausedTotal
    paused {
      instrumentId
      instrument {
        symbol
      }
      result {
        configId
        score
        reasons
        regime
      }
    }
    screeners {
      screener {
        id
        name
        owner
        version
      }
      run {
        runId
        configVersion
        paused
      }
      notRun {
        code
        reason
        kind
        guideTerm
        kindText
        cause {
          links {
            level
            subject
            status
            message
            runId
          }
        }
      }
      picked
      withheld
      top {
        instrumentId
        score
        instrument {
          symbol
        }
      }
    }
    items {
      rank
      instrumentId
      score
      regime
      sizeMultiplier
      watchOut
      instrument {
        symbol
        name
        features(names: $names) {
          name
          value
          unknown {
            code
            kind
            guideTerm
            kindText
            cause {
              links {
                level
                subject
                status
                message
                runId
              }
            }
          }
          info {
            format
            unit
            dtype
            nullMeaning
          }
        }
      }
      best {
        configId
        decision
        score
        reasons
        criteria {
          id
          outcome
        }
      }
      pickedBy {
        configId
        own
        position
        score
        decision
      }
      metrics {
        name
        value
      }
    }
  }
}

